sp_page.css:
 section.page {
  background-color: #D9EBE6 !important;
}
section.page, main.body, div.body {
  padding-top: 5px !important;
  padding-bottom: 5px !important;
}

.container-fluid {
    padding-left: 0;
    padding-right: 0;
}

  /* Fit the logo inside the existing header */
.navbar-brand img {
  max-height: 55px !important;
  width: auto !important;
}

.navbar-brand {
  height: 70px !important;
  display: flex;
  align-items: center; 
}

@media (max-width: 991px) {
  /* Prevent overlap by resetting absolute positioning on mobile/tablet */
  .padder-b-x {
    background-position: center top !important;
    padding-top: 20px !important;
  }

.padder-v {
margin-bottom: 25px !important;
  }
}
